import React from "react";

import "./tech.styles.css";

const Tech = ({ bgImgUrl, description }) => {
  const techStyle = {
    background: `url(${bgImgUrl}) center/auto 145px no-repeat`,
  };

  return (
    <div className="tech" style={techStyle}>
      <div>
        <p className="tech-content" alt={description}></p>
      </div>
    </div>
  );
};

export default Tech;
